do $catalog$declare u record;items jsonb;cap text;owner boolean;begin
 if not exists(select 1 from greenloop_private.page_capability_catalog where page_key='reports'and capabilities @> '[{"key":"report_overview"}]')then
 -- Freeze old effective permissions before expanding the catalog. A legacy
 -- Reports page grant must not inherit the newly added report sections.
 for u in select id,greenloop_private.user_capabilities(id)caps from public.user_profiles loop insert into greenloop_private.user_page_capabilities(user_id,capabilities)values(u.id,u.caps)on conflict(user_id)do nothing;end loop;
 items:='[{"key": "report_overview", "label": "View Overview", "write": false}, {"key": "report_overview_search", "label": "Search & date filters", "write": false}, {"key": "report_device_details", "label": "View Complete Device Details", "write": false}, {"key": "report_stock_received", "label": "View Stock Received", "write": false}, {"key": "report_stock_received_search", "label": "Search & date filters", "write": false}, {"key": "report_stock_received_sort", "label": "Sort table headings", "write": false}, {"key": "report_supplier_progress", "label": "View Supplier Progress", "write": false}, {"key": "report_supplier_progress_search", "label": "Search & date filters", "write": false}, {"key": "report_supplier_progress_sort", "label": "Sort table headings", "write": false}, {"key": "report_work_in_progress", "label": "View Work in Progress", "write": false}, {"key": "report_work_in_progress_search", "label": "Search & date filters", "write": false}, {"key": "report_work_in_progress_sort", "label": "Sort table headings", "write": false}, {"key": "report_parts_required", "label": "View Parts Required", "write": false}, {"key": "report_parts_required_search", "label": "Search & date filters", "write": false}, {"key": "report_parts_required_sort", "label": "Sort table headings", "write": false}, {"key": "report_parts_inventory", "label": "View Parts Inventory", "write": false}, {"key": "report_parts_inventory_search", "label": "Search & date filters", "write": false}, {"key": "report_parts_inventory_sort", "label": "Sort table headings", "write": false}, {"key": "report_technicians", "label": "View Technicians", "write": false}, {"key": "report_technicians_search", "label": "Search & date filters", "write": false}, {"key": "report_technicians_sort", "label": "Sort table headings", "write": false}, {"key": "report_final_qc", "label": "View Final QC", "write": false}, {"key": "report_final_qc_search", "label": "Search & date filters", "write": false}, {"key": "report_final_qc_sort", "label": "Sort table headings", "write": false}, {"key": "report_device_cost", "label": "View Device Cost", "write": false}, {"key": "report_device_cost_search", "label": "Search & date filters", "write": false}, {"key": "report_device_cost_sort", "label": "Sort table headings", "write": false}, {"key": "stock_grade_analysis_search", "label": "Search & date filters", "write": false}, {"key": "stock_grade_analysis_sort", "label": "Sort table headings", "write": false}, {"key": "stock_parts_cost_search", "label": "Search & date filters", "write": false}, {"key": "stock_parts_cost_sort", "label": "Sort table headings", "write": false}, {"key": "report_export_boxes", "label": "View Export Boxes", "write": false}, {"key": "report_export_boxes_search", "label": "Search & date filters", "write": false}, {"key": "report_export_boxes_sort", "label": "Sort table headings", "write": false}, {"key": "report_stock_return", "label": "View Stock Return", "write": false}, {"key": "report_stock_return_search", "label": "Search & date filters", "write": false}, {"key": "report_stock_return_sort", "label": "Sort table headings", "write": false}, {"key": "report_restricted_data", "label": "View Restricted Data", "write": false}, {"key": "report_imei_correction", "label": "View IMEI Data Correction", "write": false}, {"key": "report_imei_correction_search", "label": "Search & date filters", "write": false}, {"key": "report_damage", "label": "View Live Damage Report", "write": false}, {"key": "report_damage_search", "label": "Search & date filters", "write": false}, {"key": "report_damage_sort", "label": "Sort table headings", "write": false}, {"key": "production_view_search", "label": "Search & date filters", "write": false}, {"key": "report_deleted_history", "label": "View Deleted History", "write": false}, {"key": "report_deleted_history_search", "label": "Search & date filters", "write": false}, {"key": "report_deleted_history_sort", "label": "Sort table headings", "write": false}, {"key": "delete_export_boxes", "label": "Delete export boxes", "write": true}]'::jsonb;
 update greenloop_private.page_capability_catalog c set capabilities=c.capabilities||coalesce((select jsonb_agg(x)from jsonb_array_elements(items)x where not exists(select 1 from jsonb_array_elements(c.capabilities)y where y->>'key'=x->>'key')),'[]')where page_key='reports';
 -- Preserve the existing full Reports administrators with explicit stored
 -- section ticks. Other users receive no new report views automatically.
 for u in select c.user_id,c.capabilities from greenloop_private.user_page_capabilities c where c.capabilities->'reports'?'view'and exists(select 1 from public.user_roles ur join public.roles r on r.id=ur.role_id where ur.user_id=c.user_id and r.role_key::text in('owner','super_admin'))loop
  for cap in select 'delete_export_boxes'where u.capabilities->'reports'?'delete' union select config->>'view'from greenloop_private.report_access_sections union select config->>'search'from greenloop_private.report_access_sections where u.capabilities->'reports'?'search'and config?'search' union select config->>'sort'from greenloop_private.report_access_sections where u.capabilities->'reports'?'sort'and config?'sort'loop
   if not u.capabilities->'reports'?cap then u.capabilities:=jsonb_set(u.capabilities,'{reports}',(u.capabilities->'reports')||jsonb_build_array(cap));end if;
  end loop;
  update greenloop_private.user_page_capabilities set capabilities=u.capabilities where user_id=u.user_id;
 end loop;
end if;
end;$catalog$;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(c)order by page_key)::text)from greenloop_private.page_capability_catalog c)where identity='catalog';
create or replace function greenloop_private.rp_cap_allowed(c text,grants jsonb)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public as $$declare dep jsonb;begin
 if not coalesce(grants?'view',false)then return false;end if;
 if c in('search','sort')then return coalesce(grants?c,false)or exists(select 1 from greenloop_private.report_access_sections where config?c and grants?(config->>c)and grants?(config->>'view'));end if;
 if not coalesce(grants?c,false)then return false;end if;
 select required_views into dep from greenloop_private.report_access_dependencies where capability=c;
 if dep is null then return true;end if;
 if jsonb_typeof(dep)='string'then return grants?(dep#>>'{}');end if;
 return exists(select 1 from jsonb_array_elements_text(dep->'any')v where grants?v);
end;$$;
-- Add section dependencies to the checked capability implementation. Keep its
-- public Office Only wrapper and all existing non-Reports semantics intact.
do $cap$declare src regprocedure;ddl text;begin
 select to_regprocedure(implementation)into src from greenloop_private.office_routines where to_regprocedure(identity)='public.has_page_capability_v1(text,text)'::regprocedure;
 ddl:=pg_get_functiondef(src);
 if strpos(ddl,'greenloop_private.rp_cap_allowed')=0 then
  if strpos(ddl,$needle$coalesce((greenloop_private.user_capabilities(auth.uid())->p_page_key)?p_capability,false)$needle$)=0 then raise exception 'Reviewed capability check differs.';end if;
  ddl:=replace(ddl,$needle$coalesce((greenloop_private.user_capabilities(auth.uid())->p_page_key)?p_capability,false)$needle$,$replacement$case when p_page_key='reports'then greenloop_private.rp_cap_allowed(p_capability,greenloop_private.user_capabilities(auth.uid())->'reports')else coalesce((greenloop_private.user_capabilities(auth.uid())->p_page_key)?p_capability,false)end$replacement$);execute ddl;
 end if;
end;$cap$;
create or replace function greenloop_private.rp_require(k text,a text default 'view')returns void language plpgsql stable security definer set search_path=pg_catalog,public as $$declare c text;begin
 perform greenloop_private.require_office_network();perform greenloop_private.pf_cap('reports','view');select config->>a into c from greenloop_private.report_access_sections where report_key=k;
 if c is null then raise exception 'Unknown report action.'using errcode='22023';end if;perform greenloop_private.pf_cap('reports',c);
end;$$;
create or replace function greenloop_private.rp_dates(k text,f date,t date)returns void language plpgsql stable security definer set search_path=pg_catalog,public as $$declare today date:=(now()at time zone 'Asia/Dubai')::date;begin
 if f is null or t is null or f>t then raise exception 'Select a valid From date and To date.'using errcode='22023';end if;
 if f<>date_trunc('month',today)::date or t<>today then perform greenloop_private.rp_require(k,'search');end if;
end;$$;
do $raw$declare src regprocedure;ddl text;name text;begin
 select to_regprocedure(implementation)into src from greenloop_private.office_routines where to_regprocedure(identity)='public.get_greenloop_reports(date,date)'::regprocedure;select proname into name from pg_proc where oid=src;ddl:=pg_get_functiondef(src);execute replace(ddl,'FUNCTION greenloop_private.'||name||'(','FUNCTION greenloop_private.rp_raw(');
end;$raw$;
create or replace function greenloop_private.rp_project(data jsonb,k text)returns jsonb language sql immutable set search_path=pg_catalog as $$select case when k='overview'then jsonb_build_object('summary',data->'summary')else jsonb_build_object(k,data->k)end;$$;
create or replace function public.get_greenloop_reports(p_date_from date,p_date_to date)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare data jsonb;result jsonb:='{}';k text;c text;begin
 perform greenloop_private.require_office_network();perform greenloop_private.pf_cap('reports','view');
 for k,c in select report_key,config->>'view'from greenloop_private.report_access_sections where report_key=any(array['overview','stock_received','work_in_progress','parts_requests','parts_inventory','technicians','final_qc','costs'])loop
  if public.has_page_capability_v1('reports',c)then
   begin perform greenloop_private.rp_dates(k,p_date_from,p_date_to);exception when insufficient_privilege then continue;end;
   if data is null then data:=greenloop_private.rp_raw(p_date_from,p_date_to);end if;result:=result||greenloop_private.rp_project(data,k);
  end if;
 end loop;
 if result='{}'then raise exception 'Select an individual report permission. Reports page access alone contains no report data.'using errcode='42501';end if;
 return result||jsonb_build_object('date_from',p_date_from,'date_to',p_date_to);
end;$$;
create or replace function public.get_dashboard_report_v1(p_date_from date,p_date_to date)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare data jsonb;result jsonb:='{}';k text;begin
 perform greenloop_private.require_office_network();perform greenloop_private.pf_cap('overview','view');data:=greenloop_private.rp_raw(p_date_from,p_date_to);
 foreach k in array array['summary','stock_received','work_in_progress','parts_requests','parts_inventory','final_qc']loop result:=result||jsonb_build_object(k,data->k);end loop;return result;
end;$$;
create or replace function greenloop_private.rp_identity(data jsonb)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare k text;v jsonb;rows jsonb;result jsonb:='{}';begin
 for k,v in select *from jsonb_each(data)loop
  if jsonb_typeof(v)='array'then
   select coalesce(jsonb_agg(case when e.value?'imei'then e.value||jsonb_build_object('serial_number',coalesce(nullif(d.serial_number,''),e.value->>'serial_number',''),'specification_region',coalesce(nullif(d.specification_region,''),e.value->>'specification_region',''),'device_number',coalesce(nullif(d.device_number,''),e.value->>'device_number',''))else e.value end order by e.ordinality),'[]')into rows from jsonb_array_elements(v)with ordinality e(value,ordinality)left join lateral(select serial_number,specification_region,device_number from public.devices where imei_1=e.value->>'imei'and deleted_at is null limit 1)d on true;
   result:=result||jsonb_build_object(k,rows);
  else result:=result||jsonb_build_object(k,v);end if;
 end loop;return result;
end;$$;
create or replace function public.get_authorized_report_v1(p_report text,p_date_from date default null,p_date_to date default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare data jsonb;f date:=coalesce(p_date_from,date_trunc('month',now()at time zone 'Asia/Dubai')::date);t date:=coalesce(p_date_to,(now()at time zone 'Asia/Dubai')::date);begin
 perform greenloop_private.rp_require(p_report);perform greenloop_private.rp_dates(p_report,f,t);
 if p_report=any(array['overview','stock_received','work_in_progress','parts_requests','parts_inventory','technicians','final_qc','costs'])then data:=greenloop_private.rp_project(public.get_greenloop_reports(f,t),p_report);
 elsif p_report='export_boxes'then select jsonb_build_object('export_boxes',coalesce(jsonb_agg(to_jsonb(x)),'[]'))into data from public.get_export_box_report(f,t)x;
 elsif p_report='stock_returns'then data:=jsonb_build_object('stock_returns',public.list_active_stock_returns(f,t),'stock_return_receipt_totals',public.get_simple_stock_return_receipt_totals(null));
 elsif p_report='deleted_history'then select jsonb_build_object('deleted_history',coalesce(jsonb_agg(to_jsonb(x)),'[]'))into data from public.get_deletion_history(f,t)x;data:=data||jsonb_build_object('data_changes',coalesce((select jsonb_agg(to_jsonb(x))from public.get_data_change_history(f,t)x),'[]'));
 else raise exception 'This report uses its own authorized reader.'using errcode='22023';end if;
 return greenloop_private.rp_identity(data)||jsonb_build_object('date_from',f,'date_to',t);
end;$$;
