create or replace function greenloop_private.simple_stock_return_view_access()returns boolean language sql stable security definer set search_path=pg_catalog,public as $$select auth.uid()is not null and coalesce(public.is_active_staff(),false)and(
 public.has_page_capability_v1('reports','report_stock_return')or public.has_page_capability_v1('reports','report_overview')or public.has_page_capability_v1('reports','report_stock_received')or public.has_page_capability_v1('reports','report_supplier_progress')
 or public.has_page_capability_v1('supplier_returns','view')or public.has_page_capability_v1('supplier_return_approval','view')or public.has_page_capability_v1('supplier_return_handover','view'));$$;
create or replace function greenloop_private.rp_return_access(receipts boolean default false)returns void language plpgsql stable security definer set search_path=pg_catalog,public as $$begin
 perform greenloop_private.require_office_network();
 if public.has_page_capability_v1('reports','report_stock_return')or public.has_page_capability_v1('supplier_returns','view')or public.has_page_capability_v1('supplier_return_approval','view')or public.has_page_capability_v1('supplier_return_handover','view')then return;end if;
 if receipts and(public.has_page_capability_v1('reports','report_overview')or public.has_page_capability_v1('reports','report_stock_received')or public.has_page_capability_v1('reports','report_supplier_progress')or public.has_page_capability_v1('imei_entry','view'))then return;end if;
 raise exception 'Stock Return report permission is required.'using errcode='42501';end;$$;
