create or replace function greenloop_private.manual_damage_access(p_edit boolean default false)returns boolean language sql stable security definer set search_path=pg_catalog,public as $$select auth.uid()is not null and coalesce(public.is_active_staff(),false)and(
 case when p_edit then public.has_page_capability_v1('tv_manual_entry','entry')else public.has_page_capability_v1('tv_manual_entry','view')or public.has_page_capability_v1('reports','report_damage')end);$$;
create or replace function greenloop_private.manual_damage_management_access(p_edit boolean default false,p_reset boolean default false)returns boolean language sql stable security definer set search_path=pg_catalog,public as $$select auth.uid()is not null and coalesce(public.is_active_staff(),false)and not greenloop_private.damage_tv_only(auth.uid())and public.has_page_capability_v1('reports','view')and public.has_page_capability_v1('reports','report_damage')and case when p_reset then public.has_page_capability_v1('reports','damage_reset')when p_edit then public.has_page_capability_v1('reports','damage_correction')or public.has_page_capability_v1('reports','damage_delete')or public.has_page_capability_v1('reports','damage_reset')else true end and(not p_reset or coalesce(public.has_role(array['owner','super_admin']::public.app_role_key[]),false));$$;
