insert into greenloop_private.report_access_config_seal values(true,(select md5(jsonb_agg(to_jsonb(s)order by report_key)::text)from greenloop_private.report_access_sections s),(select md5(jsonb_agg(to_jsonb(d)order by capability)::text)from greenloop_private.report_access_dependencies d))on conflict(singleton)do update set sections_hash=excluded.sections_hash,dependencies_hash=excluded.dependencies_hash;
create or replace function public.get_report_section_access_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_b_dept_lab_transfer_version()='20261104-b-dept-lab-transfer-1'
 and(select count(*)=35 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.report_access_installation)
 and exists(select 1 from greenloop_private.report_access_config_seal where sections_hash=(select md5(jsonb_agg(to_jsonb(s)order by report_key)::text)from greenloop_private.report_access_sections s)and dependencies_hash=(select md5(jsonb_agg(to_jsonb(d)order by capability)::text)from greenloop_private.report_access_dependencies d))
 and not exists(select 1 from unnest(array['report_access_sections','report_access_dependencies','report_access_installation','report_access_config_seal'])t join pg_class c on c.oid=('greenloop_private.'||t)::regclass where not c.relrowsecurity or has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')or has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'))
 and not exists(select 1 from greenloop_private.report_access_installation where identity like 'greenloop_private.%'and(has_function_privilege('anon',to_regprocedure(identity),'EXECUTE')or has_function_privilege('authenticated',to_regprocedure(identity),'EXECUTE')))
 and not has_table_privilege('authenticated','greenloop_private.report_access_sections','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')and not has_table_privilege('anon','greenloop_private.report_access_sections','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')
 then '20261104-report-permissions-1'end;$$;
